from pathlib import Path

core = Path(__file__).resolve().parents[3] / "aram-core"

def replace_once(path, before, after):
    source = path.read_text()
    if after in source:
        return
    if source.count(before) != 1:
        raise SystemExit(f"unexpected frame pacing baseline in {path}: {before!r}")
    path.write_text(source.replace(before, after, 1))

replace_once(core / "application/machine.go",
    "\tktfPresentsPerQuantum int\n",
    "\tktfPresentsPerQuantum int\n\tinotia2FramePacing bool\n")
replace_once(core / "application/machine_ktf.go",
    "\tif budget < ktfrt.RunBudgetMin {\n\t\tbudget = ktfrt.RunBudgetMin\n\t}\n",
    "\tif budget < ktfrt.RunBudgetMin {\n\t\tbudget = ktfrt.RunBudgetMin\n\t}\n\tbudget = inotia2FrameBudget(budget, m.inotia2FramePacing)\n")
replace_once(core / "application/machine_ktf.go",
    "\tpresentLimit := ktfPresentsPerQuantumMax\n",
    "\tpresentLimit := ktfPresentsPerQuantumMax\n\tif m.inotia2FramePacing {\n\t\tpresentLimit = 1\n\t}\n")
replace_once(core / "application/machine_load.go",
    "\truntime.DeferThreads = true\n",
    "\truntime.DeferThreads = true\n\tm.inotia2FramePacing = inotia2FramePacingMatches(pkg.Descriptor.AID, pkg.Descriptor.MainClass, sha256.Sum256(pkg.Client))\n")

(core / "application/inotia2_frame_pacing.go").write_text('package application\n\nimport "crypto/sha256"\n\n// The software renderer completes one game frame at each LCD flush. Crowded\n// combat frames need more than the generic million-instruction KTF quantum;\n// spreading that work across host ticks advances guest time between fragments\n// and delays the completed picture. This is headroom to finish a frame, not a\n// change to the guest clock: the existing timer waits and quantum duration stay\n// authoritative, and runKTFSlice stops at the first completed LCD flush.\nconst inotia2CombatFrameBudget = uint64(16_000_000)\n\nfunc inotia2FramePacingMatches(aid, mainClass string, clientHash [sha256.Size]byte) bool {\n\tif aid != "010100D5" || mainClass != "Clet" {\n\t\treturn false\n\t}\n\treturn clientHash == inotia2FramePacingOriginalHash || clientHash == inotia2FramePacingPatchedHash\n}\n\nvar inotia2FramePacingOriginalHash = [sha256.Size]byte{0xe9, 0xdc, 0x70, 0xfa, 0x04, 0x19, 0x4a, 0xed, 0x2e, 0x50, 0x51, 0xa3, 0xda, 0x92, 0xff, 0x6b, 0x79, 0x99, 0x50, 0x6f, 0xd8, 0x5d, 0x69, 0xf4, 0x32, 0xb6, 0xab, 0xba, 0x7f, 0x5d, 0x85, 0x51}\nvar inotia2FramePacingPatchedHash = [sha256.Size]byte{0x04, 0x47, 0xcb, 0xaa, 0xd0, 0x6b, 0x27, 0x57, 0xf7, 0x95, 0x36, 0xae, 0x50, 0xc9, 0x4e, 0x7a, 0x6c, 0xeb, 0xf1, 0xb2, 0xb8, 0x73, 0x99, 0x77, 0xaa, 0x9f, 0x7b, 0xfa, 0x67, 0x17, 0x3a, 0x73}\n\nfunc inotia2FrameBudget(configured uint64, enabled bool) uint64 {\n\t// Preserve explicit debugger/tool budgets, including deliberately tiny\n\t// slices and larger overrides. Only the normal handset default is tuned.\n\tif enabled && configured == DefaultKTFHandsetRunBudget {\n\t\treturn inotia2CombatFrameBudget\n\t}\n\treturn configured\n}\n')
(core / "application/inotia2_frame_pacing_test.go").write_text('package application\n\nimport (\n\t"context"\n\t"encoding/binary"\n\t"testing"\n\t"time"\n\n\tktfrt "github.com/mirusu400/aram-core/application/internal/ktf"\n\tmachinecore "github.com/mirusu400/aram-core/core"\n\t"github.com/mirusu400/aram-core/cpu/interpreter"\n\t"github.com/mirusu400/aram-core/loader/ktf"\n)\n\nfunc TestInotia2FramePacingRequiresExactPackage(t *testing.T) {\n\tfor _, hash := range [][32]byte{inotia2FramePacingOriginalHash, inotia2FramePacingPatchedHash} {\n\t\tif !inotia2FramePacingMatches("010100D5", "Clet", hash) {\n\t\t\tt.Fatal("known package did not enable frame pacing")\n\t\t}\n\t\tif inotia2FramePacingMatches("010100D3", "Clet", hash) ||\n\t\t\tinotia2FramePacingMatches("010100D5", "Other", hash) {\n\t\t\tt.Fatal("lookalike descriptor enabled frame pacing")\n\t\t}\n\t\thash[0] ^= 1\n\t\tif inotia2FramePacingMatches("010100D5", "Clet", hash) {\n\t\t\tt.Fatal("modified client enabled frame pacing")\n\t\t}\n\t}\n}\n\nfunc TestInotia2CombatFrameCompletesWithoutAdvancingExtraTime(t *testing.T) {\n\tfor _, enabled := range []bool{false, true} {\n\t\tname := "generic budget fragments frame"\n\t\tif enabled { name = "title budget completes one frame" }\n\t\tt.Run(name, func(t *testing.T) {\n\t\t\t// A synthetic 1.6-million-instruction render followed by an LCD\n\t\t\t// flush, with a second runnable frame waiting behind it. No game\n\t\t\t// asset is needed to reproduce the old quantum fragmentation.\n\t\t\tclient := make([]byte, 24)\n\t\t\tfor i, op := range []uint16{0x4803, 0x3801, 0xd1fd, 0x4b03, 0x4718, 0x46c0, 0x46c0, 0x46c0} {\n\t\t\t\tbinary.LittleEndian.PutUint16(client[i*2:], op)\n\t\t\t}\n\t\t\tbinary.LittleEndian.PutUint32(client[16:], 800_000)\n\t\t\truntime, err := ktfrt.NewRuntime(interpreter.NewJIT(), ktf.Package{\n\t\t\t\tClientName: "client.bin0", Client: client,\n\t\t\t})\n\t\t\tcheck(t, err)\n\t\t\tt.Cleanup(func() { _ = runtime.CPU.Close() })\n\t\t\tcheck(t, runtime.MapImageAndHost())\n\t\t\tflush := runtime.RegisterHostCall("test.complete-frame", func(_ context.Context, r *ktfrt.Runtime) (uint32, error) {\n\t\t\t\treturn 0, r.RecordPresentation()\n\t\t\t})\n\t\t\tvar word [4]byte\n\t\t\tbinary.LittleEndian.PutUint32(word[:], flush)\n\t\t\tcheck(t, runtime.CPU.WriteMemory(ktfrt.ImageBase+20, word[:]))\n\t\t\tfor i := 0; i < 2; i++ {\n\t\t\t\ttask, err := runtime.NewTask(ktfrt.ImageBase|1, nil, i)\n\t\t\t\tcheck(t, err)\n\t\t\t\truntime.Tasks = append(runtime.Tasks, task)\n\t\t\t}\n\t\t\truntime.DefaultDisplay = 1\n\t\t\truntime.DisplayCards[1] = 2\n\t\t\tmachine := &Machine{\n\t\t\t\tcpu: runtime.CPU, state: machinecore.StatePaused,\n\t\t\t\trunBudget: DefaultRunBudget, ktfRunBudget: DefaultKTFHandsetRunBudget,\n\t\t\t\tktf: runtime, ktfStarted: true, inotia2FramePacing: enabled,\n\t\t\t}\n\t\t\tconst quantum = time.Second / 60\n\t\t\tcheck(t, machine.runKTFSlice(context.Background(), quantum))\n\t\t\twant := uint32(0)\n\t\t\tif enabled { want = 1 }\n\t\t\tif runtime.PresentCount != want {\n\t\t\t\tt.Fatalf("completed %d frames, want %d", runtime.PresentCount, want)\n\t\t\t}\n\t\t\tif got := runtime.Services.Clock.Monotonic(); got != quantum {\n\t\t\t\tt.Fatalf("guest time advanced %s, want exactly %s", got, quantum)\n\t\t\t}\n\t\t\tif enabled && runtime.Tasks[1].Instructions() != 0 {\n\t\t\t\tt.Fatal("executed an invisible second game frame")\n\t\t\t}\n\t\t})\n\t}\n}\n\nfunc TestInotia2FrameBudgetPreservesExplicitToolBudgets(t *testing.T) {\n\tfor _, configured := range []uint64{1, 32, 500_000, 4_000_000, 24_000_000} {\n\t\tif got := inotia2FrameBudget(configured, true); got != configured {\n\t\t\tt.Fatalf("explicit budget changed from %d to %d", configured, got)\n\t\t}\n\t}\n\tif got := inotia2FrameBudget(DefaultKTFHandsetRunBudget, false); got != DefaultKTFHandsetRunBudget {\n\t\tt.Fatal("unrelated title budget changed")\n\t}\n}\n')
